from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    result: List[str] = []
    depth = 0
    current = []

    for ch in paren_string:
        if ch == ' ':
            continue
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
        current.append(ch)

        if depth == 0:
            result.append(''.join(current))
            current = []

    return result
